package transcribe

import (
	"context"
	"strings"
	"testing"
	"testing/fstest"

	"github.com/stretchr/testify/require"
	"github.com/viant/bindly/resource"
	"github.com/viant/datly/internal/testharness/sqlite"
	"github.com/viant/datly/transcribe/column"
	gen "github.com/viant/datly/transcribe/generate"
	"github.com/viant/datly/typecatalog"
)

// A body scalar consumes a row generated by a nested Current graph. Neither
// a bootstrap Go DTO nor a fake descriptor may supply that row's authority.
func TestGeneratedLocalHelperReferenceAcrossCurrentGraphs(t *testing.T) {
	for _, qualifier := range []string{"self", "example.com/forward/generated"} {
		t.Run(qualifier, func(t *testing.T) {
			db := sqlite.New(t)
			require.NoError(t, db.ExecStatements(context.Background(), "CREATE TABLE records(id INTEGER PRIMARY KEY, dictionary_id INTEGER)", "CREATE TABLE dictionaries(id INTEGER PRIMARY KEY, caption TEXT)"))
			resources := resource.New()
			require.NoError(t, resources.Register("", fstest.MapFS{"sql/records.sql": {Data: []byte("SELECT id, dictionary_id, NULL AS Dictionary FROM records")}, "sql/current.sql": {Data: []byte("SELECT r.*,d.*,type(r,'" + qualifier + ".CurrentRow'),type(d,'" + qualifier + ".Dictionary','Dictionary') FROM records r LEFT JOIN dictionaries d ON d.id=r.dictionary_id AND 1=1")}}))
			text := `#package('example.com/forward/generated')
#import('self','example.com/forward/generated')
#setting($_ = $route('/records','PATCH'))
#define($_ = $Rows<[]*self.Record>(body/data).Optional())
#define($_ = $Current<?>(view/Current).Cardinality('Many').WithTypeName('self.CurrentRow') /* ${embed:sql/current.sql} */)
#define($_ = $Data<[]*self.Record>(output/body))
SELECT r.*,type(r,'self.Record'),CAST(r.Dictionary AS '*self.Dictionary'),tag(r.Dictionary,'sqlx:"-"')
FROM (${embed:sql/records.sql}) r`
			compiled, err := NewCompiler().Compile(context.Background(), &Source{Scope: "example.com/forward/generated", Name: "Records", Connector: "main", Text: text, Resources: resources, Types: typecatalog.NewCatalog(), ColumnRefiner: column.New(column.Connections{"main": db.DB})})
			require.NoError(t, err, "fresh SQL-owned helper must resolve without a preexisting Go shape")
			input, err := gen.New(gen.Input{Component: compiled.Component, TargetPackage: "example.com/forward/generated", TypeResolver: compiled.TypeResolver, ViewBindings: compiled.ViewBindings}).RuntimeInputType()
			require.NoError(t, err)
			rows, ok := input.FieldByName("Rows")
			require.True(t, ok)
			bodyDictionary, ok := rows.Type.Elem().Elem().FieldByName("Dictionary")
			require.True(t, ok)
			current, ok := input.FieldByName("Current")
			require.True(t, ok)
			currentDictionary, ok := current.Type.Elem().Elem().FieldByName("Dictionary")
			require.True(t, ok)
			require.Equal(t, currentDictionary.Type, bodyDictionary.Type, "body consumes the exact fresh Current row shape")
			_, ok = bodyDictionary.Type.Elem().FieldByName("Caption")
			require.True(t, ok, "reference must materialize the discovered shape, never an empty placeholder")
			bodyIdentity, err := compiled.Component.RootView.Identity()
			require.NoError(t, err)
			marked, err := gen.New(gen.Input{Component: compiled.Component, TargetPackage: "example.com/forward/generated", TypeResolver: compiled.TypeResolver, ViewBindings: compiled.ViewBindings, SetMarkerViews: map[string]bool{bodyIdentity: true}}).RuntimeInputType()
			require.NoError(t, err)
			markedRows, _ := marked.FieldByName("Rows")
			markedDictionary, _ := markedRows.Type.Elem().Elem().FieldByName("Dictionary")
			has, ok := markedDictionary.Type.Elem().FieldByName("Has")
			require.True(t, ok, "scalar SQL-owned helper must inherit body presence")
			_, ok = has.Type.Elem().FieldByName("Caption")
			require.True(t, ok)
		})
	}
}

func TestGeneratedLocalHelperReferenceRejectsInvalidAuthority(t *testing.T) {
	const pkg = "example.com/forward/generated"
	for _, tc := range []struct{ name, reference, current, extra, message string }{
		{name: "missing", reference: "self.Missing", current: "SELECT d.*,type(d,'self.Dictionary') FROM dictionaries d", message: "was not found"},
		{name: "foreign missing same basename", reference: "foreign.Dictionary", current: "SELECT d.*,type(d,'self.Dictionary') FROM dictionaries d", message: "was not found"},
		{name: "ambiguous owners", reference: "self.Dictionary", current: "SELECT d.*,type(d,'self.Dictionary') FROM dictionaries d", extra: "#define($_ = $Other<?>(view/Other).Cardinality('Many').WithTypeName('self.Dictionary') /* SELECT id FROM dictionaries */)", message: "multiple SQL owners"},
		{name: "named cycle", reference: "self.Dictionary", current: "SELECT d.*,type(d,'self.Dictionary'),CAST(d.Parent AS '*self.Record') FROM (SELECT id,caption,NULL AS Parent FROM dictionaries) d", message: "dependency cycle"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			db := sqlite.New(t)
			require.NoError(t, db.ExecStatements(context.Background(), "CREATE TABLE records(id INTEGER PRIMARY KEY)", "CREATE TABLE dictionaries(id INTEGER PRIMARY KEY, caption TEXT)"))
			text := `#package('` + pkg + `')
#import('self','` + pkg + `')
#import('foreign','example.com/foreign')
#setting($_ = $route('/records','PATCH'))
#define($_ = $Rows<[]*self.Record>(body/data).Optional())
#define($_ = $Current<?>(view/Current).Cardinality('Many').WithTypeName('self.Dictionary') /* ` + tc.current + ` */)
` + tc.extra + `
SELECT r.*,type(r,'self.Record'),CAST(r.Dictionary AS '*` + tc.reference + `'),tag(r.Dictionary,'sqlx:"-"')
FROM (SELECT id,NULL AS Dictionary FROM records) r`
			_, err := NewCompiler().Compile(context.Background(), &Source{Scope: pkg, Name: "Records", Connector: "main", Text: text, Types: typecatalog.NewCatalog(), ColumnRefiner: column.New(column.Connections{"main": db.DB})})
			require.Error(t, err)
			require.True(t, strings.Contains(err.Error(), tc.message), "wrong failure: %v", err)
		})
	}
}
